import React, { useState, useEffect } from 'react';
import axios from 'axios';
import './CSS/Products.css';

const Products = () => {
  const [products, setProducts] = useState([]);
  const [loading, setLoading] = useState(true);
  const [selectedCategory, setSelectedCategory] = useState('All');

  useEffect(() => {
    fetchProducts();
  }, []);

 const fetchProducts = async () => {
    try {
      setLoading(true);
      const response = await axios.get('http://localhost:4000/api/seller/products');
      
      // Ensure response.data is an array before setting state
      if (Array.isArray(response.data)) {
        setProducts(response.data);
      } else if (response.data && Array.isArray(response.data.products)) {
        setProducts(response.data.products);
      } else {
        setProducts([]);
      }
    } catch (err) {
      console.error('Error fetching products:', err);
      setProducts([]); // Fallback to an empty array so .filter() never crashes
    } finally {
      setLoading(false);
    }
  };

  const filteredProducts = products.filter((product) => {
    if (selectedCategory === 'All') return true;
    return product.category?.toLowerCase() === selectedCategory.toLowerCase();
  });

  const categories = ['All', 'Smartphones', 'Audio', 'Wearables', 'Accessories'];

  return (
    <div className="products-container">
      <div className="products-hero">
        <h1>Explore All Gadgets</h1>
        <p>Discover top-tier mobile devices, wearables, and high-performance tech accessories.</p>

        <div className="category-tabs">
          {categories.map((cat) => (
            <button
              key={cat}
              className={`category-btn ${selectedCategory === cat ? 'active' : ''}`}
              onClick={() => setSelectedCategory(cat)}
            >
              {cat}
            </button>
          ))}
        </div>
      </div>

      <div className="products-grid-wrapper">
        {loading ? (
          <p>Loading products from database...</p>
        ) : filteredProducts.length === 0 ? (
          <p>No products available in this category.</p>
        ) : (
          <div className="products-grid">
            
          </div>
        )}
      </div>
    </div>
  );
};

export default Products;
